/* Fragenkatalog Teil 1: Grundlagen (Architekturen, Medien/RAID, SAN, Optimierung, Verfügbarkeit, Backup) */
window.ASE = window.ASE || {};
ASE.qb = ASE.qb || [];
ASE.qb.push(
/* ---------- Speicherarchitekturen ---------- */
{id:"gr01",t:"grundlagen",type:"single",q:"Welche Speicherart legt Daten zusammen mit Metadaten und einer eindeutigen ID in einem flachen Namensraum ab und wird typischerweise per HTTP/REST (z. B. S3-API) angesprochen?",o:["Block Storage","File Storage","Object Storage","Direct Attached Storage"],a:[2],e:"Object Storage speichert Objekte (Daten + umfangreiche Metadaten + eindeutige ID) in einem flachen Namensraum. Der Zugriff erfolgt über APIs wie S3 – ideal für sehr große Mengen unstrukturierter Daten, Backup-Ziele, Archive und KI-Data-Lakes."},
{id:"gr02",t:"grundlagen",type:"single",q:"Ein Kunde benötigt eine gemeinsam genutzte Dateifreigabe für Windows-Clients inklusive NTFS-ähnlicher Berechtigungen. Welche Lösung passt am besten?",o:["SAN mit Fibre-Channel-LUNs","NAS mit SMB-Protokoll","Object Storage mit S3","DAS über SAS"],a:[1],e:"Dateifreigaben für Windows-Clients werden über NAS mit dem SMB-Protokoll (früher CIFS) bereitgestellt. Das Speichersystem verwaltet das Dateisystem und die Berechtigungen; ein SAN liefert dagegen nur Blöcke."},
{id:"gr03",t:"grundlagen",type:"multi",q:"Welche Aussagen treffen auf Block Storage zu? (Wählen Sie ZWEI.)",o:["Der Host verwaltet das Dateisystem auf dem bereitgestellten Volume.","Der Zugriff erfolgt über Protokolle wie FC, iSCSI oder NVMe-oF.","Der Zugriff erfolgt über eine REST-API mit Buckets.","Das Speichersystem verwaltet Datei-Locks für mehrere Clients.","Jeder Datensatz besitzt erweiterbare benutzerdefinierte Metadaten."],a:[0,1],e:"Block Storage stellt LUNs/Volumes bereit, die über SAN-Protokolle (FC, iSCSI, NVMe-oF, SAS) adressiert werden; das Dateisystem (z. B. NTFS, VMFS, XFS) legt der Host selbst an. Buckets/REST und Metadaten sind Merkmale von Object Storage, Datei-Locks von NAS."},
{id:"gr04",t:"grundlagen",type:"single",q:"Was ist der wichtigste Nachteil von Direct Attached Storage (DAS) in größeren Umgebungen?",o:["Sehr hohe Latenz durch das Netzwerk","Speicherinseln: Kapazität kann nicht flexibel zwischen Servern geteilt werden","DAS unterstützt keine SSDs","DAS benötigt immer Fibre-Channel-Switches"],a:[1],e:"DAS ist einem einzelnen Server direkt zugeordnet. Dadurch entstehen Speicherinseln mit schlechter Auslastung; Funktionen wie Cluster-Failover oder VM-Mobilität über gemeinsamen Speicher sind kaum möglich. Latenz ist bei DAS dagegen meist sehr gut."},
{id:"gr05",t:"grundlagen",type:"single",q:"Welches Protokoll wird klassisch für Dateifreigaben in Linux-/UNIX-Umgebungen verwendet?",o:["SMB","NFS","iSCSI","S3"],a:[1],e:"NFS (Network File System) ist das Standardprotokoll für Dateifreigaben unter Linux/UNIX. SMB ist das Windows-Pendant, iSCSI ist ein Block-Protokoll und S3 eine Object-API."},
{id:"gr06",t:"grundlagen",type:"single",q:"Was beschreibt Hyperconverged Infrastructure (HCI) am besten?",o:["Getrennte Server, Switches und Arrays, die als validiertes Bundle verkauft werden","Knoten, die Compute, Storage und Virtualisierung softwaredefiniert vereinen und durch Hinzufügen weiterer Knoten skalieren","Ein Array, das Block, File und Object gleichzeitig anbietet","Ein reines Backup-Appliance-Konzept"],a:[1],e:"HCI kombiniert Compute, Speicher (softwaredefiniert) und Virtualisierung in jedem Knoten; skaliert wird durch weitere Knoten (Beispiel: HPE SimpliVity). Nachteil: Compute und Kapazität wachsen immer gemeinsam."},
{id:"gr07",t:"grundlagen",type:"single",q:"Worin unterscheidet sich disaggregierte HCI (dHCI) von klassischer HCI?",o:["dHCI verwendet ausschließlich Object Storage","Compute und Storage skalieren unabhängig voneinander, werden aber gemeinsam wie HCI verwaltet","dHCI benötigt keinen Hypervisor","dHCI funktioniert nur in der Public Cloud"],a:[1],e:"Bei dHCI sind Server und externes Array getrennte Bausteine, die sich unabhängig erweitern lassen, aber mit HCI-ähnlicher Einfachheit verwaltet werden. HPE bot dies mit Nimble/Alletra an; heute adressiert u. a. HPE Private Cloud Business Edition mit Alletra Storage MP B10000 dieses Modell."},
{id:"gr08",t:"grundlagen",type:"single",q:"Was kennzeichnet Software-Defined Storage (SDS)?",o:["Speicherfunktionen sind fest in proprietären ASICs implementiert","Die Speichersoftware ist von der Hardware entkoppelt und läuft auf Standardservern","SDS ist eine andere Bezeichnung für Tape-Libraries","SDS bedeutet, dass nur SSDs eingesetzt werden"],a:[1],e:"SDS trennt die Speicherintelligenz (Software) von der Hardware. Sie läuft auf Industriestandard-Servern oder als virtuelle Appliance (z. B. HPE StoreOnce VSA, HPE SimpliVity)."},
{id:"gr09",t:"grundlagen",type:"single",q:"Für welchen Workload ist Object Storage am WENIGSTEN geeignet?",o:["Langzeitarchiv für Millionen Dateien","Backup-Ziel mit Unveränderbarkeit (Object Lock)","Transaktionale OLTP-Datenbank mit Sub-Millisekunden-Latenz","Data Lake für KI-Training"],a:[2],e:"OLTP-Datenbanken benötigen kleine, zufällige I/Os mit sehr geringer Latenz – das ist die Domäne von Block Storage. Object Storage glänzt bei Skalierung, Metadaten und Durchsatz für unstrukturierte Daten."},
{id:"gr10",t:"grundlagen",type:"match",q:"Ordnen Sie jedem Anwendungsfall die passende Speicherart zu.",pairs:[["Oracle-OLTP-Datenbank","Block Storage"],["Home-Verzeichnisse für Windows-Clients","File Storage (SMB)"],["Backup-Repository mit S3 Object Lock","Object Storage"],["Gemeinsamer Projektordner für Linux-Server","File Storage (NFS)"],["VMware-VMFS-Datastore","Block Storage"]],e:"Datenbanken und VMFS nutzen Blöcke (LUNs/Namespaces). Dateifreigaben laufen über SMB (Windows) bzw. NFS (Linux). S3 Object Lock ist eine Object-Storage-Funktion für unveränderbare Backups."},
{id:"gr11",t:"grundlagen",type:"single",q:"Was beschreibt Erasure Coding am besten?",o:["Daten werden einfach auf ein zweites Laufwerk gespiegelt","Daten werden in Daten- und Paritätsfragmente zerlegt und über viele Laufwerke/Knoten verteilt","Daten werden verschlüsselt und anschließend gelöscht","Ein Verfahren zur Deduplizierung"],a:[1],e:"Erasure Coding (k Daten- + m Paritätsfragmente) verteilt Daten über viele Laufwerke oder Knoten und toleriert m Ausfälle. Es ist typisch für Scale-out- und Object-Storage (z. B. X10000) und effizienter als Spiegelung."},
{id:"gr12",t:"grundlagen",type:"single",q:"Was versteht man unter „Unified Storage“?",o:["Ein Array, das Block- und File-Protokolle (ggf. auch Object) auf einer Plattform bereitstellt","Eine Storage-Lösung mit nur einem Controller","Speicher, der ausschließlich in der Public Cloud liegt","Die Kombination aus Tape und Disk in einem Gehäuse"],a:[0],e:"Unified Storage bedient mehrere Zugriffsarten (Block und File, teils Object) auf einer gemeinsamen Plattform. Die HPE Alletra Storage MP B10000 vereint seit Release 5/6 Block und File auf derselben disaggregierten Architektur."},
{id:"gr13",t:"grundlagen",type:"single",q:"Welche Aussage zu NAS und SAN ist korrekt?",o:["NAS liefert Block-Zugriff über Fibre Channel","SAN liefert Datei-Zugriff über SMB","NAS liefert Datei-Zugriff über Ethernet, SAN liefert Block-Zugriff über ein dediziertes Speichernetz","NAS und SAN sind identisch"],a:[2],e:"NAS = dateibasiert (NFS/SMB) über das IP-Netz. SAN = blockbasiert (FC, iSCSI, NVMe-oF) über ein dediziertes Speichernetz; das Dateisystem liegt beim Host."},
{id:"gr14",t:"grundlagen",type:"single",q:"Was unterscheidet Converged Infrastructure (CI) von HCI?",o:["CI integriert Compute, Storage und Netzwerk als vorvalidierten Stack aus weiterhin getrennten Komponenten","CI nutzt nur softwaredefinierten Speicher in den Servern","CI unterstützt keine Virtualisierung","Es gibt keinen Unterschied"],a:[0],e:"Converged Infrastructure ist ein vorab getestetes, gemeinsam geliefertes Paket aus separaten Komponenten (Server, Array, Switches). HCI verschmilzt Compute und Storage dagegen softwaredefiniert in denselben Knoten."},
{id:"gr15",t:"grundlagen",type:"multi",q:"Welche Vorteile bietet ein SAN gegenüber DAS? (Wählen Sie ZWEI.)",o:["Zentrale Kapazitätspools mit besserer Auslastung","Gemeinsamer Speicher ermöglicht Cluster-Failover und VM-Mobilität","Geringere Kosten bei genau einem Server","Es wird kein Netzwerk benötigt","Multipathing wird überflüssig"],a:[0,1],e:"Ein SAN konsolidiert Kapazität und ermöglicht Shared Storage für Cluster und Live-Migration. Für einen einzelnen Server ist DAS günstiger; Multipathing wird im SAN gerade empfohlen."},
{id:"gr16",t:"grundlagen",type:"single",q:"Welche Speicherart nutzt typischerweise Buckets als Container für Daten?",o:["Block Storage","Object Storage","File Storage","Tape-Libraries"],a:[1],e:"Buckets sind die Container im Object Storage (S3). Darin liegen Objekte, die über Schlüssel (Keys) adressiert werden."},

/* ---------- Laufwerke & RAID ---------- */
{id:"me01",t:"medien",type:"single",q:"Wie viele gleichzeitige Laufwerksausfälle innerhalb einer RAID-Gruppe toleriert RAID 6?",o:["Einen","Zwei","Drei","Keinen"],a:[1],e:"RAID 6 nutzt doppelte Parität (P+Q) und übersteht zwei gleichzeitige Laufwerksausfälle. Die HPE Alletra Storage MP B10000 nutzt ausschließlich RAID 6."},
{id:"me02",t:"medien",type:"single",q:"Wie hoch ist die klassische Write Penalty (Back-end-I/Os pro Front-end-Schreibvorgang) bei RAID 5?",o:["1","2","4","6"],a:[2],e:"RAID 5: Daten lesen, Parität lesen, Daten schreiben, Parität schreiben = 4 Back-end-I/Os. RAID 1/10 = 2, RAID 6 = 6."},
{id:"me03",t:"medien",type:"single",q:"Wie hoch ist die klassische Write Penalty bei RAID 6?",o:["2","4","6","8"],a:[2],e:"RAID 6 muss Daten und zwei Paritäten lesen und schreiben: 6 Back-end-I/Os pro zufälligem Front-end-Schreibvorgang."},
{id:"me04",t:"medien",type:"single",q:"Ein Server hat 8 Laufwerke à 2 TB in RAID 10. Wie viel Nutzkapazität steht (vor Dateisystem-Overhead) zur Verfügung?",o:["4 TB","8 TB","12 TB","16 TB"],a:[1],e:"RAID 10 spiegelt jedes Laufwerk: 50 % Effizienz. 8 × 2 TB = 16 TB roh → 8 TB nutzbar."},
{id:"me05",t:"medien",type:"single",q:"Wie viel Nutzkapazität ergibt ein RAID-6-Set (10+2) aus 12 SSDs à 3,84 TB – ohne weiteren Overhead?",o:["30,72 TB","38,4 TB","42,24 TB","46,08 TB"],a:[1],e:"Bei 10+2 tragen 10 Laufwerke Daten: 10 × 3,84 TB = 38,4 TB (Effizienz 83,3 %). Real kommen Sparing, Metadaten und Headroom hinzu – Sizing-Tools berücksichtigen das."},
{id:"me06",t:"medien",type:"single",q:"Welche Aussage zu QLC-SSDs im Vergleich zu TLC-SSDs ist korrekt?",o:["QLC speichert 3 Bit pro Zelle und hat höhere Lebensdauer","QLC speichert 4 Bit pro Zelle, bietet höhere Dichte und geringere Kosten pro TB, aber geringere Schreib-Endurance","QLC ist immer schneller beim Schreiben","QLC wird nur in Tape-Laufwerken verwendet"],a:[1],e:"QLC = 4 Bit/Zelle: günstiger und dichter, aber niedrigere DWPD. Laut B10000-QuickSpecs haben die QLC-SSDs 0,26 DWPD, TLC-SSDs 1,0 DWPD – ideal für leselastige Workloads; Sizing-Tools (z. B. Ninja Online) verwenden.",src:"b10qs"},
{id:"me07",t:"medien",type:"single",q:"Was gibt der Wert DWPD bei SSDs an?",o:["Die Datenübertragungsrate pro Sekunde","Wie oft die gesamte Kapazität pro Tag über die Garantielaufzeit beschrieben werden kann","Die Anzahl der Lesezugriffe pro Tag","Den Stromverbrauch pro Tag"],a:[1],e:"Drive Writes Per Day: Anzahl vollständiger Überschreibungen der Kapazität pro Tag über die gesamte Lebensdauer – ein Maß für die Schreib-Endurance."},
{id:"me08",t:"medien",type:"single",q:"Was ist ein wesentlicher Vorteil von NVMe gegenüber SAS/SATA?",o:["NVMe benötigt keinen Strom","NVMe kommuniziert direkt über PCIe mit vielen parallelen Queues und deutlich geringerer Latenz","NVMe ist ein Bandformat","NVMe funktioniert nur mit HDDs"],a:[1],e:"NVMe wurde für Flash entwickelt: direkte PCIe-Anbindung, bis zu 64K Queues mit je bis zu 64K Befehlen, schlanker Protokollstack ohne SCSI-Übersetzung → geringe Latenz, hohe Parallelität."},
{id:"me09",t:"medien",type:"single",q:"Welcher Laufwerkstyp bietet die niedrigsten Kosten pro TB für kapazitätsorientierte Daten?",o:["15K-SAS-HDD","10K-SAS-HDD","7.2K Midline/NL-SAS-HDD","TLC-NVMe-SSD"],a:[2],e:"7.2K-Midline-Laufwerke (NL-SAS) sind auf Kapazität und Kosten optimiert (z. B. bis 24 TB bei der MSA Gen7), liefern aber nur wenige IOPS (ca. 75–100)."},
{id:"me10",t:"medien",type:"multi",q:"Welche Vorteile bietet verteiltes Sparing/verteiltes RAID wie MSA-DP+? (Wählen Sie ZWEI.)",o:["Schnellere Rebuilds, da viele Laufwerke parallel beteiligt sind","Keine ungenutzten Hot-Spare-Laufwerke – alle Laufwerke tragen zur Performance bei","Parität ist nicht mehr nötig","Beliebige Laufwerksgrößen ohne jede Einschränkung mischbar","Die Nutzkapazität verdoppelt sich"],a:[0,1],e:"MSA-DP+ verteilt Daten und Spare-Kapazität über alle Laufwerke der Disk Group: sehr schnelle Rebuilds, keine Idle-Spares. Laut QuickSpecs sollte das Kapazitätsverhältnis größter/kleinster Disk aber nicht über 2 liegen.",src:"msaqs"},
{id:"me11",t:"medien",type:"single",q:"Warum werden in Enterprise-Arrays SAS- statt SATA-Laufwerke bevorzugt?",o:["SAS-Laufwerke sind Dual-Port-fähig und können redundant an zwei Controller angebunden werden","SATA ist schneller als SAS","SAS-Laufwerke benötigen keine Firmware","SATA unterstützt keine HDDs"],a:[0],e:"SAS ist dual-ported und vollduplex – jedes Laufwerk ist über zwei Pfade/Controller erreichbar, was für Hochverfügbarkeit nötig ist. SATA ist single-ported."},
{id:"me12",t:"medien",type:"single",q:"Warum gewinnt doppelte Parität (RAID 6) bei sehr großen HDDs an Bedeutung?",o:["Große Laufwerke rebuilden schneller","Lange Rebuild-Zeiten erhöhen das Risiko eines zweiten Fehlers (Ausfall oder Lesefehler) während des Rebuilds","RAID 6 ist immer schneller als RAID 5","Große Laufwerke unterstützen kein RAID 5"],a:[1],e:"Bei großen Laufwerken dauert ein Rebuild Stunden bis Tage. In dieser Zeit kann ein weiterer Ausfall oder ein nicht korrigierbarer Lesefehler (URE) auftreten – RAID 6 bzw. verteiltes RAID reduziert dieses Risiko."},
{id:"me13",t:"medien",type:"single",q:"Wofür unterstützt die HPE MSA Gen7 RAID 0?",o:["Für alle Daten-Disk-Groups","Nur für den SSD-Read-Cache","Nur für Remote Snap","Gar nicht"],a:[1],e:"Laut MSA-Gen7-QuickSpecs werden RAID 1, 5, 6, 10 und MSA-DP+ für Daten unterstützt; RAID 0 (NRAID) nur für den Read Cache, da dieser keine einzigen Datenkopien enthält.",src:"msaqs"},
{id:"me14",t:"medien",type:"single",q:"Eine SSD hat 15,36 TB (dezimal). Wie viel ist das ungefähr in TiB (binär)?",o:["15,36 TiB","16,9 TiB","13,97 TiB","12,3 TiB"],a:[2],e:"1 TiB = 2^40 Byte ≈ 1,0995 TB. 15,36 TB ÷ 1,0995 ≈ 13,97 TiB. HPE-QuickSpecs geben Kapazitäten oft in TB und TiB an – beim Sizing auf die Einheit achten."},
{id:"me15",t:"medien",type:"single",q:"Was ist eine Self-Encrypting Drive (SED)?",o:["Ein Laufwerk, das Daten per Hardware im Laufwerk selbst verschlüsselt","Ein Laufwerk ohne Verschlüsselung","Eine Software zur Dateiverschlüsselung auf dem Host","Ein Bandlaufwerk mit WORM"],a:[0],e:"SEDs verschlüsseln alle Daten im Laufwerkscontroller (typisch AES-256) ohne Performanceverlust. Die Schlüssel werden vom Array lokal oder über einen externen Key Manager verwaltet; FIPS-validierte Varianten erfüllen Behördenanforderungen."},
{id:"me16",t:"medien",type:"match",q:"Ordnen Sie jedem RAID-Level die passende Eigenschaft zu.",pairs:[["RAID 0","Striping ohne Redundanz"],["RAID 1","Spiegelung, 50 % Nutzkapazität"],["RAID 5","Einfache Parität, Write Penalty 4"],["RAID 6","Doppelte Parität, toleriert 2 Ausfälle"],["RAID 10","Gespiegelte Stripes, Write Penalty 2"]],e:"Merkhilfe Write Penalty: RAID 0 = 1, RAID 1/10 = 2, RAID 5 = 4, RAID 6 = 6."},
{id:"me17",t:"medien",type:"single",q:"Welche Laufwerkstechnologie wurde in HPE 3PAR/Primera als besonders schneller Cache (Storage Class Memory) eingesetzt?",o:["LTO-Tape","SCM (z. B. Intel Optane)","SATA-HDD","Shingled Magnetic Recording"],a:[1],e:"Storage Class Memory (SCM) liegt in Latenz zwischen DRAM und NAND-Flash. HPE nutzte SCM (Optane) als Cache-Beschleuniger in 3PAR/Primera; Optane wurde inzwischen vom Hersteller eingestellt."},

/* ---------- SAN & Host-Anbindung ---------- */
{id:"sa01",t:"san",type:"single",q:"Was identifiziert ein WWPN (World Wide Port Name) im Fibre Channel?",o:["Einen kompletten Switch","Einen einzelnen Port eines FC-Knotens (z. B. HBA-Port)","Eine LUN auf dem Array","Ein VLAN"],a:[1],e:"Der WWPN ist eine 64-Bit-Adresse für einen konkreten FC-Port. Der WWNN identifiziert den Knoten (z. B. den HBA) insgesamt. Zoning und Host-Definitionen basieren meist auf WWPNs."},
{id:"sa02",t:"san",type:"single",q:"Wo werden Zoning und LUN-Masking jeweils konfiguriert?",o:["Beides auf dem Host","Zoning auf dem FC-Switch, LUN-Masking auf dem Storage-Array","Zoning auf dem Array, LUN-Masking auf dem Switch","Beides im Hypervisor"],a:[1],e:"Zoning steuert im Fabric (Switch), welche Ports einander sehen. LUN-Masking (Selective Storage Presentation, Export/Host-Mapping) steuert im Array, welche Hosts welche Volumes sehen. Beides zusammen = Defense in Depth."},
{id:"sa03",t:"san",type:"single",q:"Welche Zoning-Best-Practice empfiehlt HPE für FC-SANs?",o:["Eine große Zone mit allen Hosts und Arrays","Single-Initiator-Zoning: jede Zone enthält einen Initiator und dessen Targets","Kein Zoning, nur LUN-Masking","Zonen nur nach Switch-Ports ohne Doku"],a:[1],e:"Single-Initiator (Single-Target) Zoning verhindert, dass Initiatoren sich gegenseitig stören (z. B. durch RSCNs) und begrenzt Fehler. Alternativ automatisiert HPE Smart SAN bzw. Peer Zoning die Zonenerstellung."},
{id:"sa04",t:"san",type:"single",q:"Ein Server-HBA wird auf einen anderen Port desselben Switches umgesteckt. Bei welcher Zoning-Art ist KEINE Zoning-Anpassung nötig?",o:["Port-Zoning (Domain,Port)","WWPN-Zoning","Bei keiner","Bei beiden muss angepasst werden"],a:[1],e:"WWPN-Zoning folgt dem Gerät, egal an welchem Port es steckt. Port-Zoning ist an den physischen Switch-Port gebunden und müsste angepasst werden."},
{id:"sa05",t:"san",type:"single",q:"Welchen TCP-Port verwendet iSCSI standardmäßig?",o:["445","2049","3260","8080"],a:[2],e:"iSCSI nutzt TCP 3260. 445 = SMB, 2049 = NFS."},
{id:"sa06",t:"san",type:"single",q:"Welches Namensformat ist für iSCSI-Initiatoren und -Targets am gebräuchlichsten?",o:["WWPN","IQN (z. B. iqn.1991-05.com.microsoft:host01)","NQN","MAC-Adresse"],a:[1],e:"iSCSI nutzt IQNs (iSCSI Qualified Name: iqn.JJJJ-MM.umgekehrte-Domain:Bezeichner) oder seltener EUI-Namen. NQNs werden bei NVMe-oF verwendet."},
{id:"sa07",t:"san",type:"multi",q:"Welche Best Practices gelten für iSCSI-Speichernetze? (Wählen Sie ZWEI.)",o:["Speicherverkehr in eigenem VLAN/Subnetz isolieren","Jumbo Frames, wenn genutzt, durchgängig auf Host, Switch und Array konfigurieren","iSCSI im selben VLAN wie den Client-Verkehr betreiben","Jumbo Frames nur auf dem Host aktivieren","LACP-Teaming statt MPIO für die Pfadredundanz nutzen"],a:[0,1],e:"iSCSI gehört in ein dediziertes Netz/VLAN. Eine MTU-Inkonsistenz (Jumbo Frames nur teilweise) führt zu Fragmentierung oder Paketverlusten. Für Pfadredundanz wird MPIO statt Link-Aggregation empfohlen."},
{id:"sa08",t:"san",type:"single",q:"Was ist der Hauptvorteil von NVMe/TCP?",o:["Es benötigt spezielle RDMA-Netzwerkkarten","NVMe-oF-Performancevorteile über Standard-Ethernet/TCP ohne dediziertes FC-Netz oder Lossless-Ethernet","Es funktioniert nur mit Tape","Es ersetzt RAID"],a:[1],e:"NVMe/TCP transportiert NVMe-Befehle über normales TCP/IP-Ethernet. Laut B10000-QuickSpecs erhält man so die Vorteile einer NVMe-Fabric, ohne sich auf ein dediziertes Speichernetz wie Fibre Channel festzulegen.",src:"b10qs"},
{id:"sa09",t:"san",type:"single",q:"Was setzt NVMe over RoCE (RDMA over Converged Ethernet) typischerweise voraus?",o:["Ein FC-Fabric","RDMA-fähige NICs und ein verlustfreies (lossless) Ethernet mit DCB/PFC","Nur Wi-Fi","SAS-Expander"],a:[1],e:"RoCEv2 nutzt RDMA für sehr geringe Latenz und benötigt RDMA-NICs sowie meist Lossless Ethernet (Priority Flow Control). Die B10000 nutzt 100GbE RoCEv2 intern zwischen Controllern und JBOFs."},
{id:"sa10",t:"san",type:"single",q:"Welche SAN-Topologie platziert Hosts an Edge-Switches und Storage an zentralen Core-Switches/Directors?",o:["Kaskade","Ring","Core-Edge","Full Mesh"],a:[2],e:"Core-Edge ist die gängigste skalierbare Topologie: vorhersehbare Hop-Anzahl, Storage zentral am Core. Bei sehr großen Fabrics nutzt man Edge-Core-Edge (Storage an eigenen Edge-Switches)."},
{id:"sa11",t:"san",type:"single",q:"Was ist der Hauptnachteil einer Full-Mesh-Topologie bei wachsender Switch-Anzahl?",o:["Hohe Hop-Anzahl","Die Anzahl der ISLs wächst stark (n·(n–1)/2) und verbraucht viele Ports","Keine Redundanz","Nur ein Switch möglich"],a:[1],e:"Im Full Mesh ist jeder Switch mit jedem verbunden: max. ein Hop, aber die ISL-Zahl wächst quadratisch. Daher nur für wenige Switches sinnvoll."},
{id:"sa12",t:"san",type:"single",q:"Welches Problem hat eine Kaskaden-Topologie (Daisy Chain)?",o:["Sie ist zu teuer","Steigende Hop-Anzahl und Single Points of Failure zwischen den Switches","Sie unterstützt keine ISLs","Sie benötigt Directors"],a:[1],e:"In einer Kaskade hängt jeder Switch am nächsten. Fällt ein Switch oder ISL in der Mitte aus, wird das Fabric geteilt; zudem steigen Hops und Latenz."},
{id:"sa13",t:"san",type:"single",q:"Was ist die Best Practice für hochverfügbare SANs?",o:["Ein einziges großes Fabric mit vielen ISLs","Zwei physisch getrennte Fabrics (A/B); jeder Host und jedes Array ist an beide angebunden","Alle Hosts an einen Director","Nur iSCSI verwenden"],a:[1],e:"Zwei unabhängige Fabrics verhindern, dass ein Fehler oder eine Fehlkonfiguration (z. B. Zoning-Fehler, Firmware-Bug) den gesamten Speicherzugriff unterbricht. Multipathing nutzt beide Fabrics."},
{id:"sa14",t:"san",type:"single",q:"Was leistet ALUA (Asymmetric Logical Unit Access)?",o:["Es verschlüsselt LUNs","Es meldet Pfadzustände (z. B. active/optimized, active/non-optimized), damit die Multipath-Software bevorzugt optimierte Pfade nutzt","Es ist ein RAID-Level","Es ersetzt Zoning"],a:[1],e:"Bei asymmetrischen Arrays (z. B. MSA mit Pool-Besitz pro Controller) sind Pfade über den besitzenden Controller optimiert. ALUA teilt das dem Host mit. Peer Persistence nutzt ALUA-Pfadzustände für transparentes Failover."},
{id:"sa15",t:"san",type:"single",q:"Was ermöglicht NPIV (N_Port ID Virtualization)?",o:["Mehrere virtuelle WWPNs über einen physischen FC-Port","Die Verbindung zweier Fabrics","iSCSI über FC","Verschlüsselung auf dem ISL"],a:[0],e:"NPIV erlaubt mehrere N_Port-IDs/WWPNs auf einem physischen Port – z. B. für virtuelle Maschinen oder Blade-Interconnects. Verwandt: NPV/Access-Gateway-Modus bei Switches."},
{id:"sa16",t:"san",type:"single",q:"Wie heißt ein FC-Switch-Port, der als Inter-Switch-Link (ISL) zu einem anderen Switch dient?",o:["N_Port","F_Port","E_Port","NL_Port"],a:[2],e:"E_Port = Expansion Port (ISL). F_Port = Fabric-Port für Endgeräte, N_Port = Node-Port am Host/Array."},
{id:"sa17",t:"san",type:"single",q:"Was ist mit SSP (Selective Storage Presentation) gemeint?",o:["Eine Snapshot-Technologie","Die gezielte Präsentation von Volumes nur an definierte Hosts (LUN-Masking) auf dem Array","Ein Switch-Protokoll","Eine Methode zur Deduplizierung"],a:[1],e:"SSP ist ein (historischer HP-)Begriff für LUN-Masking: Das Array stellt ein Volume nur den Hosts (WWPN/IQN) zur Verfügung, denen es zugewiesen ist. Er taucht ausdrücklich in den HPE0-J83-Zielen auf.",src:"j83"},
{id:"sa18",t:"san",type:"single",q:"Worin unterscheidet sich Hard Zoning von Soft Zoning?",o:["Hard Zoning wird in der Switch-Hardware für jeden Frame durchgesetzt; Soft Zoning filtert nur die Name-Server-Antworten","Soft Zoning ist sicherer als Hard Zoning","Hard Zoning gibt es nur bei iSCSI","Es gibt keinen Unterschied"],a:[0],e:"Soft (software-basiertes) Zoning blendet Geräte nur in Name-Server-Abfragen aus – wer die Adresse kennt, könnte sie erreichen. Hard Zoning erzwingt die Trennung im ASIC des Switches."},
{id:"sa19",t:"san",type:"single",q:"Welche Aufgabe hat Multipathing-Software (MPIO, DM-Multipath, VMware NMP)?",o:["Daten zu deduplizieren","Mehrere Pfade zu einem Volume für Redundanz und Lastverteilung zu nutzen","Zonen anzulegen","Firmware zu aktualisieren"],a:[1],e:"Multipathing erkennt mehrere Pfade zum selben Volume, verteilt die Last (z. B. Round Robin) und schaltet bei Pfadausfall transparent um. Es ist Voraussetzung für unterbrechungsfreie Updates (z. B. MSA-Online-Firmware-Update)."},
{id:"sa20",t:"san",type:"single",q:"Welche FC-Geschwindigkeit gehört zur Generation „Gen 7“?",o:["16GFC","32GFC","64GFC","128GFC"],a:[2],e:"Gen 5 = 16GFC, Gen 6 = 32GFC, Gen 7 = 64GFC. HPE B-series SN8700B-Directors unterstützen 64 Gb/s."},
{id:"sa21",t:"san",type:"single",q:"Was beschreibt das Fan-in-/Oversubscription-Verhältnis im SAN-Design?",o:["Verhältnis von Host-Ports (bzw. Host-Bandbreite) zu Storage-Ports oder ISL-Bandbreite","Verhältnis von SSDs zu HDDs","Anzahl der Zonen pro Switch","Verhältnis von Lese- zu Schreib-I/O"],a:[0],e:"Da nicht alle Hosts gleichzeitig Volllast erzeugen, teilen sich mehrere Host-Ports einen Storage- oder ISL-Port. Das Verhältnis muss zum Workload passen, sonst entstehen Engpässe."},
{id:"sa22",t:"san",type:"match",q:"Ordnen Sie jedem Protokoll den passenden Transport zu.",pairs:[["Fibre Channel","Eigenes verlustfreies FC-Fabric mit Buffer Credits"],["iSCSI","SCSI über TCP/IP-Ethernet"],["FCoE","FC-Frames über verlustfreies Ethernet (DCB) ohne TCP/IP"],["NVMe/TCP","NVMe-Befehle über TCP/IP-Ethernet"],["NVMe/FC","NVMe-Befehle über ein FC-Fabric"]],e:"FC nutzt Credit-basierte Flusskontrolle. FCoE braucht DCB (PFC/ETS). NVMe-oF gibt es über FC, TCP und RDMA (RoCE/InfiniBand)."},
{id:"sa23",t:"san",type:"single",q:"Was bewirkt ISL Trunking bei HPE B-series-Switches?",o:["Mehrere ISLs werden zu einer logischen Verbindung mit Lastverteilung auf Frame-Ebene gebündelt","ISLs werden verschlüsselt","Zonen werden automatisch erstellt","Ports werden deaktiviert"],a:[0],e:"Trunking fasst mehrere physische ISLs zu einem logischen Trunk zusammen; die Last wird gleichmäßig verteilt, und der Ausfall eines Links unterbricht den Trunk nicht."},
{id:"sa24",t:"san",type:"single",q:"Was ist die Domain-ID in einem FC-Fabric?",o:["Die eindeutige Kennung eines Switches im Fabric, Teil der 24-Bit-FC-Adresse","Der Name eines VLANs","Eine LUN-Nummer","Die Seriennummer des Arrays"],a:[0],e:"Jeder Switch eines Fabrics benötigt eine eindeutige Domain-ID (1–239). Sie bildet das erste Byte der 24-Bit-FCID (Domain, Area, Port). Doppelte Domain-IDs verhindern das Zusammenführen von Fabrics."},
{id:"sa25",t:"san",type:"single",q:"Wie heißt bei NVMe-oF das Gegenstück zur LUN?",o:["Namespace","Bucket","Share","Zone"],a:[0],e:"NVMe adressiert Namespaces (NSID) innerhalb eines NVM-Subsystems; Hosts und Subsysteme werden über NQNs benannt. Das ALUA-Pendant heißt ANA (Asymmetric Namespace Access)."},

/* ---------- Speicheroptimierung ---------- */
{id:"ef01",t:"effizienz",type:"single",q:"Was ist das Prinzip von Thin Provisioning?",o:["Volumes reservieren sofort die gesamte physische Kapazität","Physische Kapazität wird erst beim tatsächlichen Schreiben zugewiesen","Daten werden komprimiert","Daten werden auf Tape ausgelagert"],a:[1],e:"Thin Provisioning stellt Hosts große virtuelle Volumes bereit, belegt aber nur geschriebene Daten. Risiko: Overcommitment – Kapazitätsschwellen und Alerts sind Pflicht."},
{id:"ef02",t:"effizienz",type:"single",q:"Wie wird bei Thin Provisioning freigegebener Speicher (z. B. nach dem Löschen von Dateien) an das Array zurückgegeben?",o:["Gar nicht","Über SCSI UNMAP/TRIM vom Host bzw. Zero-Detect im Array (Space Reclamation)","Durch Neustart des Arrays","Durch RAID-Rebuild"],a:[1],e:"Space Reclamation: Das Betriebssystem/der Hypervisor sendet UNMAP (bzw. NVMe Deallocate), oder das Array erkennt Nullblöcke. Die MSA Gen7 listet „Space Reclamation“ als Thin-Technologie.",src:"msaqs"},
{id:"ef03",t:"effizienz",type:"single",q:"Worin unterscheiden sich Deduplizierung und Kompression?",o:["Dedupe entfernt identische Blöcke über den Datenbestand hinweg; Kompression verkleinert einzelne Datenblöcke","Beides ist identisch","Kompression entfernt Duplikate, Dedupe verschlüsselt","Dedupe funktioniert nur auf Tape"],a:[0],e:"Deduplizierung speichert identische Blöcke (per Hash-Fingerprint erkannt) nur einmal. Kompression kodiert Daten platzsparender. Beide werden oft kombiniert."},
{id:"ef04",t:"effizienz",type:"single",q:"Was ist der Unterschied zwischen Inline- und Post-Process-Deduplizierung?",o:["Inline dedupliziert, bevor die Daten auf die Medien geschrieben werden; Post-Process erst nachträglich","Post-Process ist immer schneller","Inline benötigt eine Landing Zone","Es gibt keinen Unterschied"],a:[0],e:"Inline spart sofort Kapazität und Schreibzugriffe (wichtig für Flash), kostet aber CPU im Datenpfad. Post-Process schreibt zunächst alles und benötigt temporär mehr Kapazität."},
{id:"ef05",t:"effizienz",type:"single",q:"Welchen Vorteil hat quellseitige (source-side) Deduplizierung, wie sie z. B. HPE StoreOnce Catalyst bietet?",o:["Sie erhöht den Netzwerkverkehr","Nur eindeutige Daten werden über das Netzwerk übertragen – weniger Bandbreite und schnellere Backups","Sie macht Backups unveränderbar","Sie ersetzt Snapshots"],a:[1],e:"Bei Source-side Dedupe (Catalyst „low bandwidth“) prüft bereits der Media-Server bzw. das Plugin, welche Blöcke neu sind. Ideal für Backups über WAN oder aus Außenstellen."},
{id:"ef06",t:"effizienz",type:"single",q:"Welche Daten erzielen typischerweise die SCHLECHTESTE Datenreduktion?",o:["VDI-Images mit vielen identischen Betriebssystemen","Bereits komprimierte oder verschlüsselte Daten (z. B. Videos, verschlüsselte Datenbanken)","Wiederholte Voll-Backups","Testdatenbanken als Kopien der Produktion"],a:[1],e:"Verschlüsselte und vorkomprimierte Daten haben kaum Redundanz. VDI und wiederholte Backups deduplizieren dagegen sehr gut. Daher Datenreduktionsraten immer workloadabhängig sizen."},
{id:"ef07",t:"effizienz",type:"single",q:"Was macht Sub-LUN-Tiering (z. B. MSA Automated Tiering)?",o:["Verschiebt ganze Volumes nachts auf Tape","Verschiebt häufig genutzte Seiten/Bereiche eines Volumes automatisch auf schnellere Tiers und kalte Daten auf langsamere","Spiegelt Daten auf ein zweites Array","Verschlüsselt Daten je nach Zugriff"],a:[1],e:"Die MSA verschiebt „Pages“ je nach Zugriffshäufigkeit zwischen Performance- (SSD), Standard- (10K) und Archive-Tier (7.2K). So genügt ein kleiner SSD-Anteil für viele heiße Daten.",src:"msaqs"},
{id:"ef08",t:"effizienz",type:"single",q:"Wie heißt die QoS-Funktion im ArcusOS der HPE Alletra Storage MP B10000 (aus der 3PAR/Primera-Linie)?",o:["Adaptive Optimization","Priority Optimization","Virtual Tier Affinity","Peer Motion"],a:[1],e:"Priority Optimization legt Limits bzw. Ziele für IOPS, Bandbreite und Latenz pro Volume-Set fest und verhindert „Noisy Neighbors“. Laut QuickSpecs ist es Teil der ArcusOS-Software.",src:"b10qs"},
{id:"ef09",t:"effizienz",type:"single",q:"Welchen Vorteil bietet Wide Striping?",o:["Daten liegen auf möglichst wenigen Laufwerken","Alle Laufwerke eines Systems tragen zur Performance bei und Hotspots werden vermieden","Es spart Lizenzkosten","Es ersetzt die Parität"],a:[1],e:"Wide Striping verteilt jedes Volume über alle verfügbaren Laufwerke. Dadurch steigt die Performance mit jeder Erweiterung, und einzelne Laufwerke werden nicht zum Engpass."},
{id:"ef10",t:"effizienz",type:"single",q:"Ein System hat 50 TB nutzbare Kapazität. Bei einer angenommenen Datenreduktion von 4:1 beträgt die effektive Kapazität …",o:["12,5 TB","54 TB","200 TB","400 TB"],a:[2],e:"Effektive Kapazität = Nutzkapazität × Reduktionsrate = 50 TB × 4 = 200 TB. Die B10000-QuickSpecs rechnen genauso mit 4:1 „Data Compaction“ (StoreMore-Guarantee)."},
{id:"ef11",t:"effizienz",type:"single",q:"Welche VAAI-Primitive lagert das Kopieren von VMDKs (z. B. Klonen) an das Array aus?",o:["ATS (Atomic Test & Set)","XCOPY (Copy Offload/Full Copy)","Block Zeroing","UNMAP"],a:[1],e:"XCOPY lässt das Array Daten intern kopieren, statt sie über Host und SAN zu schieben. ATS ersetzt SCSI-Reservierungen beim VMFS-Locking, Block Zeroing lagert das Nullen aus."},
{id:"ef12",t:"effizienz",type:"single",q:"Warum sind Kapazitäts-Alerts bei Thin Provisioning besonders wichtig?",o:["Weil Thin Volumes langsamer sind","Weil bei einem vollen Pool Schreibvorgänge aller thin Volumes im Pool fehlschlagen können","Weil Thin Provisioning RAID deaktiviert","Weil Alerts Lizenzen benötigen"],a:[1],e:"Bei Overcommitment kann der physische Pool volllaufen, obwohl die Hosts noch „freien“ Platz sehen. Schwellwerte, Trendanalysen (z. B. in DSCC/InfoSight) und Reclamation sind Pflicht."},
{id:"ef13",t:"effizienz",type:"multi",q:"Welche Technologien zählt HPE bei der „Data Compaction“ (4:1) der B10000 mit? (Wählen Sie DREI.)",o:["Thin Provisioning","Deduplizierung","Kompression","RAID-6-Parität","Hot-Spare-Laufwerke"],a:[0,1,2],e:"Laut B10000-QuickSpecs basiert die effektive Kapazität auf 4:1 Data Compaction aus Thin Provisioning, Deduplizierung, Kompression und Copy-Technologien (Snapshots/Clones). RAID-Parität verringert dagegen die Nutzkapazität.",src:"b10qs"},
{id:"ef14",t:"effizienz",type:"single",q:"Was ist ein SSD-Read-Cache (wie bei der MSA Gen7)?",o:["Ein permanenter Speicherort für alle Schreibdaten","Eine SSD-Erweiterung des Controller-Caches, die häufig gelesene Daten von HDD-Pools beschleunigt","Ein Tape-Puffer","Ein Verschlüsselungsmodul"],a:[1],e:"Der Read Cache enthält nur Kopien häufig gelesener Daten. Fällt eine Cache-SSD aus, gehen keine Daten verloren – deshalb ist dort auch RAID 0 zulässig. Bei der MSA Gen7 bis 8,34 TB pro Array.",src:"msaqs"},

/* ---------- Verfügbarkeit & Multi-Site ---------- */
{id:"ve01",t:"verfuegbarkeit",type:"single",q:"Was beschreibt der RPO (Recovery Point Objective)?",o:["Die maximale Dauer bis zur Wiederherstellung","Den maximal tolerierbaren Datenverlust, gemessen als Zeitspanne","Die Anzahl der Backup-Kopien","Die Bandbreite der Replikation"],a:[1],e:"RPO = wie viele Daten (in Zeit) maximal verloren gehen dürfen. RPO 0 erfordert synchrone Replikation; Zerto erreicht RPOs im Sekundenbereich."},
{id:"ve02",t:"verfuegbarkeit",type:"single",q:"Was beschreibt der RTO (Recovery Time Objective)?",o:["Den maximal tolerierbaren Datenverlust","Die maximal tolerierbare Zeit, bis ein Dienst nach einem Ausfall wieder verfügbar ist","Die Aufbewahrungsdauer von Backups","Die Latenz einer Replikationsstrecke"],a:[1],e:"RTO = maximale Ausfallzeit bis zur Wiederherstellung. Kurze RTOs erfordern z. B. transparente Failover-Lösungen (Peer Persistence) oder schnelle Restore-Verfahren (Snapshots, Zerto-Journal)."},
{id:"ve03",t:"verfuegbarkeit",type:"single",q:"Welche Aussage zu synchroner Replikation ist korrekt?",o:["Der Host erhält die Schreibbestätigung erst, wenn die Daten auf beiden Systemen gesichert sind; RPO = 0, aber distanz-/latenzbegrenzt","Sie eignet sich besonders für interkontinentale Distanzen","Der RPO beträgt immer mehrere Stunden","Sie benötigt keine Bandbreite"],a:[0],e:"Jede Schreiboperation wartet auf die Remote-Bestätigung. Dadurch erhöht die Round-Trip-Time die Schreiblatenz – synchrone Replikation ist daher auf Metro-Distanzen begrenzt."},
{id:"ve04",t:"verfuegbarkeit",type:"single",q:"Wann ist asynchrone Replikation die richtige Wahl?",o:["Wenn RPO = 0 zwingend ist","Bei großen Distanzen oder begrenzter Bandbreite, wenn ein RPO > 0 akzeptabel ist","Nur innerhalb eines Racks","Nur für Tape"],a:[1],e:"Asynchrone Replikation bestätigt lokal und überträgt zeitversetzt (periodisch oder streaming). Die Anwendungslatenz bleibt unbeeinflusst, der RPO ist aber größer als null."},
{id:"ve05",t:"verfuegbarkeit",type:"single",q:"Wie viel Ausfallzeit pro Jahr entspricht ungefähr einer Verfügbarkeit von 99,999 % („five nines“)?",o:["ca. 8,8 Stunden","ca. 52,6 Minuten","ca. 5,26 Minuten","ca. 31,5 Sekunden"],a:[2],e:"Jahr = 525.600 min. 0,001 % davon ≈ 5,26 min. 99,99 % ≈ 52,6 min, 99,9 % ≈ 8,76 h, 99,9999 % (six nines, früher Nimble/Alletra 6000) ≈ 31,5 s."},
{id:"ve06",t:"verfuegbarkeit",type:"single",q:"Welche Komponenten benötigt HPE Peer Persistence für automatisches transparentes Failover?",o:["Asynchrone Replikation und ein Tape-Laufwerk","Synchrone Remote-Copy-Replikation zwischen zwei Arrays und einen Quorum Witness an einem dritten Standort","Nur ein einzelnes Array mit zwei Controllern","Ein StoreOnce-System"],a:[1],e:"Peer Persistence spiegelt Volumes synchron zwischen zwei Arrays; beide präsentieren das Volume mit derselben Identität. Der Quorum Witness (VM am dritten Standort) entscheidet bei Ausfällen über das automatische Umschalten.",src:"pp"},
{id:"ve07",t:"verfuegbarkeit",type:"single",q:"Wo sollte der Quorum Witness einer Peer-Persistence-Konfiguration platziert werden?",o:["Auf einem der beiden Arrays","Am Standort A","An einem dritten Standort außerhalb der Fehlerdomänen beider Arrays","Auf einem Host im SAN von Standort B"],a:[2],e:"Nur an einem dritten Standort kann der Witness zwischen Array-Ausfall, Standortausfall und Ausfall der Verbindung zwischen den Standorten (Split Brain) unterscheiden.",src:"pp"},
{id:"ve08",t:"verfuegbarkeit",type:"single",q:"Was passiert in einer Peer-Persistence-Umgebung, wenn nur der Quorum Witness ausfällt?",o:["Alle Volumes werden sofort offline genommen","Der I/O läuft normal weiter, aber das automatische transparente Failover ist deaktiviert, bis der Witness wieder erreichbar ist","Die Replikation wird asynchron","Beide Arrays starten neu"],a:[1],e:"Der Witness speichert keine Daten. Sein Ausfall beeinträchtigt den laufenden Betrieb nicht, nur die Automatik für den Fall eines weiteren Fehlers fehlt."},
{id:"ve09",t:"verfuegbarkeit",type:"single",q:"Was bedeutet „Uniform Host Access“ in einem Metro-Cluster?",o:["Hosts an beiden Standorten haben Pfade zu beiden Arrays","Jeder Host sieht nur das lokale Array","Alle Hosts nutzen dasselbe Betriebssystem","Es gibt nur einen Standort"],a:[0],e:"Bei Uniform Access sind Hosts beider Standorte mit beiden Arrays verbunden (Cross-Connect). So kann bei Array-Ausfall transparent auf das andere Array umgeschaltet werden, ohne dass VMs neu starten."},
{id:"ve10",t:"verfuegbarkeit",type:"single",q:"Was beschreibt eine 3DC-Replikationstopologie (Three Data Center)?",o:["Drei Kopien im selben Array","Synchrone Replikation zu einem nahen Standort plus asynchrone Replikation zu einem entfernten Standort","Drei Backups pro Tag","Drei Controller pro Array"],a:[1],e:"3DC kombiniert RPO 0 im Metro-Bereich (synchron) mit Schutz gegen regionale Katastrophen (asynchron über große Distanz)."},
{id:"ve11",t:"verfuegbarkeit",type:"single",q:"Wozu dient eine Konsistenzgruppe (z. B. Remote-Copy-Gruppe) bei der Replikation?",o:["Sie komprimiert Daten","Sie bewahrt die Schreibreihenfolge über mehrere zusammengehörige Volumes (z. B. Datenbank-Daten und -Logs)","Sie definiert RAID-Level","Sie ersetzt Zoning"],a:[1],e:"Anwendungen mit mehreren Volumes benötigen einen konsistenten gemeinsamen Zeitpunkt. Remote-Copy-Gruppen replizieren alle Mitglieder write-order-konsistent; Zerto erreicht dasselbe mit VPGs."},
{id:"ve12",t:"verfuegbarkeit",type:"single",q:"Woran muss die Bandbreite einer synchronen Replikationsstrecke ausgerichtet werden?",o:["An der durchschnittlichen täglichen Änderungsrate","An der Spitzen-Schreiblast (Peak Write Throughput)","An der Lesegeschwindigkeit","An der Anzahl der Volumes"],a:[1],e:"Da jede Schreiboperation sofort übertragen werden muss, bestimmt die Peak-Schreiblast die benötigte Bandbreite. Bei asynchroner Replikation reicht die Änderungsrate innerhalb des RPO-Fensters."},
{id:"ve13",t:"verfuegbarkeit",type:"single",q:"Wie arbeitet HPE MSA Remote Snap?",o:["Synchrone Spiegelung jedes Writes","Asynchrone, snapshot-basierte Replikation, bei der nur die Änderungen zwischen zwei Snapshots übertragen werden","Replikation auf Tape","Replikation in die Public Cloud via S3"],a:[1],e:"Laut QuickSpecs ist Remote Snap eine asynchrone Replikation: Ein neuer Snapshot wird mit dem vorherigen verglichen, nur geänderte Daten werden über FC oder iSCSI übertragen. Es unterstützt auch „Many-to-1“ (bis 4).",src:"msaqs"},
{id:"ve14",t:"verfuegbarkeit",type:"multi",q:"Welche Maßnahmen eliminieren Single Points of Failure im Speicherpfad? (Wählen Sie ZWEI.)",o:["Array mit zwei redundanten Controllern","Zwei unabhängige Fabrics mit Multipathing auf den Hosts","Ein einzelner Dual-Port-HBA pro Server","RAID 0 für bessere Performance","Ein großer Director statt zweier Switches"],a:[0,1],e:"Redundante Controller und zwei getrennte Fabrics mit MPIO vermeiden SPOFs. Ein einzelner HBA (auch mit zwei Ports) bleibt ein SPOF, ebenso ein einziges Fabric – auch wenn ein Director intern redundant ist."},
{id:"ve15",t:"verfuegbarkeit",type:"single",q:"Was ist VMware vSphere Metro Storage Cluster (vMSC)?",o:["Ein Backup-Tool","Ein über zwei Standorte gestreckter vSphere-Cluster mit synchron replizierter Speicherlösung wie HPE Peer Persistence","Ein Tape-Format","Eine Lizenzform"],a:[1],e:"vMSC ist ein zertifiziertes Design für Stretched Cluster. Speicherseitig liefert z. B. Peer Persistence die synchron replizierten, an beiden Standorten zugreifbaren Datastores."},
{id:"ve16",t:"verfuegbarkeit",type:"single",q:"Was kennzeichnet Active Peer Persistence bei der HPE Alletra Storage MP B10000?",o:["Asynchrone Replikation mit Stunden-RPO","Synchrone Replikation mit transparentem Failover zwischen aktiven Standorten – Basis der Zero-RPO/RTO-Garantie","Ein Backup in die Cloud","Ein reines Migrationswerkzeug"],a:[1],e:"Laut HPE kombiniert Active Peer Persistence synchrone Replikation mit transparentem Failover über aktive Standorte. Darauf baut die 2025 eingeführte Zero-RTO/RPO-Garantie auf (Voraussetzungen u. a. identische Array-Konfiguration, mind. 3 Jahre SaaS).",src:"pr2505"},
{id:"ve17",t:"verfuegbarkeit",type:"single",q:"Was bedeutet „Split Brain“ in einem Zwei-Standort-Cluster?",o:["Beide Seiten verlieren die Verbindung zueinander und könnten unabhängig weiterschreiben – mit Gefahr inkonsistenter Daten","Ein Array hat zwei Controller","Ein Volume wird geklont","Eine Zone enthält zwei Initiatoren"],a:[0],e:"Ohne Schiedsrichter (Quorum/Witness) können beide Seiten glauben, die andere sei ausgefallen. Der Witness verhindert, dass beide gleichzeitig aktiv schreiben."},

/* ---------- Datensicherung (Theorie) ---------- */
{id:"ba01",t:"backup",type:"single",q:"Was sichert ein inkrementelles Backup?",o:["Alle Daten","Alle Änderungen seit dem letzten Backup beliebigen Typs","Alle Änderungen seit dem letzten Voll-Backup","Nur Systemdateien"],a:[1],e:"Inkrementell = Änderungen seit dem letzten (vollen oder inkrementellen) Backup. Schnell und platzsparend, beim Restore werden aber Full + alle Inkremente benötigt."},
{id:"ba02",t:"backup",type:"single",q:"Was sichert ein differenzielles Backup?",o:["Änderungen seit dem letzten Voll-Backup","Änderungen seit dem letzten inkrementellen Backup","Nur gelöschte Dateien","Den kompletten Datenbestand"],a:[0],e:"Differenziell = Änderungen seit dem letzten Voll-Backup. Die Sicherungen wachsen bis zum nächsten Full, der Restore braucht aber nur Full + letztes Differenzial."},
{id:"ba03",t:"backup",type:"single",q:"Sonntag Voll-Backup, Montag bis Donnerstag differenzielle Backups. Donnerstagabend ist ein Restore nötig. Welche Sicherungen werden benötigt?",o:["Nur das Donnerstag-Backup","Voll-Backup + alle vier Differenziale","Voll-Backup + das Differenzial von Donnerstag","Voll-Backup + das Differenzial von Montag"],a:[2],e:"Jedes Differenzial enthält alle Änderungen seit dem Full. Daher genügen Full + das letzte Differenzial. Bei inkrementellen Backups wären Full + Mo + Di + Mi + Do nötig."},
{id:"ba04",t:"backup",type:"single",q:"Was ist ein synthetisches Voll-Backup?",o:["Ein Voll-Backup direkt von der Produktion","Ein Voll-Backup, das auf dem Backup-Ziel aus vorhandenem Full und Inkrementen zusammengesetzt wird, ohne die Produktion erneut zu lesen","Ein Backup auf Tape","Ein Snapshot"],a:[1],e:"Synthetic Full reduziert die Last auf Produktionssystemen und das Backup-Fenster. Deduplizierende Ziele wie StoreOnce (Catalyst) unterstützen solche Operationen effizient."},
{id:"ba05",t:"backup",type:"single",q:"Wofür stehen die zusätzliche „1“ und die „0“ in der 3-2-1-1-0-Regel?",o:["1 Cloud-Kopie und 0 Kosten","1 Offline-/Air-Gap-/unveränderbare Kopie und 0 Fehler bei der Wiederherstellungsprüfung","1 Tape und 0 Snapshots","1 Admin und 0 Passwörter"],a:[1],e:"3 Kopien, 2 Medientypen, 1 Kopie extern, 1 Kopie offline/immutable (Schutz vor Ransomware), 0 Fehler – Backups müssen regelmäßig per Restore-Test verifiziert werden."},
{id:"ba06",t:"backup",type:"single",q:"Warum ersetzt ein Array-Snapshot allein kein Backup?",o:["Snapshots sind immer zu groß","Snapshots liegen auf demselben System und teilen Datenblöcke mit dem Original – fällt das Array aus, sind beide verloren","Snapshots können nicht wiederhergestellt werden","Snapshots sind verschlüsselt"],a:[1],e:"Snapshots sind ideal für schnelle Wiederherstellung (niedriger RTO), schützen aber nicht vor Array-Verlust, Standortausfall oder Angriffen auf das Array. Erst eine Kopie auf ein anderes System/Medium ist ein Backup."},
{id:"ba07",t:"backup",type:"single",q:"Wie funktioniert ein Copy-on-Write-Snapshot (COW)?",o:["Neue Schreibvorgänge landen an einer neuen Stelle","Vor dem Überschreiben wird der Originalblock in den Snapshot-Bereich kopiert – das kostet zusätzliche I/Os","Das komplette Volume wird sofort kopiert","Es werden nur Metadaten gelöscht"],a:[1],e:"COW: Lesen + Kopieren des alten Blocks + Schreiben des neuen = Zusatzlast bei Writes. Redirect-on-Write schreibt neue Daten dagegen einfach an eine neue Stelle und passt nur Zeiger an."},
{id:"ba08",t:"backup",type:"single",q:"Was kennzeichnet Redirect-on-Write-Snapshots (ROW)?",o:["Neue Writes werden an einen neuen Ort geschrieben, der Snapshot behält die Zeiger auf die alten Blöcke – keine Kopier-Zusatzlast","Jeder Write wird doppelt geschrieben","Snapshots werden auf Tape umgeleitet","ROW ist nur für File Storage"],a:[0],e:"ROW vermeidet die Kopieroperation von COW und ist daher bei vielen Snapshots performanter. Log-strukturierte Systeme (z. B. Nimble CASL) arbeiten nach diesem Prinzip."},
{id:"ba09",t:"backup",type:"single",q:"Welcher Windows-Dienst sorgt für anwendungskonsistente Snapshots/Backups (z. B. bei SQL Server oder Exchange)?",o:["DFS","VSS (Volume Shadow Copy Service)","WSUS","DHCP"],a:[1],e:"VSS koordiniert Anwendung (Writer), Requestor (Backup-Software) und Provider (z. B. Array-Hardware-Provider), damit Daten vor dem Snapshot konsistent geflusht werden. Ohne VSS ist ein Snapshot nur crash-konsistent."},
{id:"ba10",t:"backup",type:"single",q:"Welche native Kapazität hat eine LTO-9-Kassette?",o:["12 TB","18 TB","30 TB","45 TB"],a:[1],e:"LTO-9: 18 TB nativ, 45 TB komprimiert (2,5:1). LTO-8: 12/30 TB. LTO-10 (2025): 30 TB nativ. HPE StoreEver MSL-Libraries werden u. a. mit LTO-9-Laufwerken angeboten.",src:"storeever"},
{id:"ba11",t:"backup",type:"single",q:"Was ermöglicht LTFS (Linear Tape File System)?",o:["Deduplizierung auf Tape","Dateisystem-ähnlichen Zugriff auf Bänder (z. B. Drag & Drop) dank Partitionierung ab LTO-5","Synchrone Replikation","Verschlüsselung von Festplatten"],a:[1],e:"LTFS nutzt die Partitionierung (ab LTO-5): eine Index-Partition und eine Daten-Partition. Bänder werden so wie ein Wechseldatenträger lesbar – praktisch für Datenaustausch und Archiv."},
{id:"ba12",t:"backup",type:"single",q:"Wofür steht WORM bei Speichermedien?",o:["Write Once, Read Many – Daten können nicht verändert oder gelöscht werden","Write Often, Read Mostly","Wide Object Retention Mode","Write-Optimized RAID Mode"],a:[0],e:"WORM-Medien (z. B. LTO-WORM-Kassetten) oder WORM-Funktionen (Immutability, Object Lock) schützen vor Manipulation und erfüllen Compliance-Anforderungen."},
{id:"ba13",t:"backup",type:"single",q:"Was ist ein „Air Gap“ in der Datensicherung?",o:["Ein Kühlungskonzept im Rechenzentrum","Eine physische oder logische Trennung einer Sicherungskopie vom Produktionsnetz, sodass Angreifer sie nicht erreichen können","Ein Kompressionsverfahren","Ein FC-Port-Typ"],a:[1],e:"Klassisch: ausgelagerte Tapes. Logisch: isolierte Vaults (z. B. Zerto Cyber Resilience Vault) oder zeitweise getrennte Kopien. Ziel ist eine Kopie, die Ransomware nicht verschlüsseln kann."},
{id:"ba14",t:"backup",type:"single",q:"Was beschreibt das GFS-Prinzip (Grandfather-Father-Son)?",o:["Ein Replikationsverfahren","Ein Aufbewahrungsschema mit täglichen (Son), wöchentlichen (Father) und monatlichen (Grandfather) Sicherungen","Ein RAID-Level","Eine Zoning-Methode"],a:[1],e:"GFS reduziert die Zahl aufbewahrter Sicherungen bei langer Historie: viele tägliche für kurze Zeit, weniger wöchentliche, wenige monatliche/jährliche für lange Zeit."},
{id:"ba15",t:"backup",type:"single",q:"Was ermöglicht Changed Block Tracking (CBT) bei VM-Backups?",o:["Der Hypervisor protokolliert geänderte Blöcke, sodass inkrementelle Image-Backups nur diese lesen müssen","Es verschlüsselt VMs","Es löscht alte Snapshots","Es repliziert VMs synchron"],a:[0],e:"Mit CBT (VMware) bzw. RCT (Hyper-V) muss die Backup-Software nicht die gesamte virtuelle Disk scannen – inkrementelle Backups werden deutlich schneller („incremental forever“)."},
{id:"ba16",t:"backup",type:"single",q:"Ein Kunde schafft seine nächtlichen Voll-Backups nicht mehr im Backup-Fenster. Welche Maßnahme hilft am direktesten?",o:["Mehr RAM im Fileserver","Umstellung auf Incremental-forever mit synthetischen Vollsicherungen bzw. Backups aus Array-Snapshots","Backups nur noch monatlich","RAID 0 auf dem Backup-Ziel"],a:[1],e:"Incremental forever, synthetische Fulls, Snapshot-basierte Backups und source-side Dedupe (Catalyst) verkürzen die Belastung der Produktion drastisch, ohne den Schutz zu reduzieren."},
{id:"ba17",t:"backup",type:"match",q:"Ordnen Sie jedem Begriff die passende Definition zu.",pairs:[["RPO","Maximal tolerierbarer Datenverlust (Zeit)"],["RTO","Maximal tolerierbare Wiederherstellungszeit"],["Retention","Aufbewahrungsdauer einer Sicherung"],["Immutability","Unveränderbarkeit einer Kopie für eine definierte Zeit"],["Air Gap","Trennung einer Kopie vom Produktionsnetz"]],e:"Diese Begriffe bilden die Basis jeder Datensicherungsstrategie und tauchen in allen HPE-Storage-Prüfungen auf."},
{id:"ba18",t:"backup",type:"single",q:"Welcher Unterschied besteht zwischen crash-konsistenten und anwendungskonsistenten Sicherungen?",o:["Crash-konsistent entspricht einem Stromausfall-Zustand; anwendungskonsistent stellt sicher, dass die Anwendung ihre Daten vor der Sicherung sauber geschrieben hat","Es gibt keinen Unterschied","Anwendungskonsistent ist immer schneller","Crash-konsistent funktioniert nur mit Tape"],a:[0],e:"Crash-konsistente Kopien entsprechen einem harten Ausfall – Datenbanken müssen beim Start ggf. recovern. Anwendungskonsistente Kopien (VSS, Datenbank-Plugins) sind sofort sauber nutzbar."}
);
